CREATE TABLE public.account_programs(user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE,occupation text NOT NULL,category text NOT NULL,member_kind text NOT NULL,completed_at timestamptz NOT NULL DEFAULT now(),points_awarded boolean NOT NULL DEFAULT true,sharing_active boolean NOT NULL DEFAULT false,sharing_started_at timestamptz,referral_rewarded_at timestamptz,referral_free_until timestamptz,reminder_consent boolean NOT NULL DEFAULT false,CHECK(length(trim(occupation)) BETWEEN 1 AND 100),CHECK(length(trim(category)) BETWEEN 1 AND 100),CHECK(member_kind IN('seeker','employer','owner','business','service')));
GRANT SELECT ON public.account_programs TO authenticated; GRANT ALL ON public.account_programs TO service_role;
ALTER TABLE public.account_programs ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_program_read ON public.account_programs FOR SELECT TO authenticated USING((user_id=auth.uid() OR public.has_role(auth.uid(),'admin')) AND public.account_allowed(auth.uid()));
CREATE TABLE public.program_evidence(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,paths text[] NOT NULL,hashes text[] NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL DEFAULT now()+interval '24 hours',status text NOT NULL DEFAULT 'received',CHECK(status='received'),CHECK(cardinality(hashes)=6),CHECK(cardinality(paths) IN(0,6)));
GRANT SELECT ON public.program_evidence TO authenticated; GRANT ALL ON public.program_evidence TO service_role;
ALTER TABLE public.program_evidence ENABLE ROW LEVEL SECURITY;
CREATE POLICY program_evidence_read ON public.program_evidence FOR SELECT TO authenticated USING((user_id=auth.uid() OR public.has_role(auth.uid(),'admin')) AND public.account_allowed(auth.uid()));
CREATE TABLE public.program_reminders(user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,day date NOT NULL,notification_id uuid REFERENCES public.notifications(id),PRIMARY KEY(user_id,day));
GRANT SELECT ON public.program_reminders TO authenticated; GRANT ALL ON public.program_reminders TO service_role;
ALTER TABLE public.program_reminders ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_program_reminders ON public.program_reminders FOR SELECT TO authenticated USING(user_id=auth.uid() AND public.account_allowed(auth.uid()));
CREATE FUNCTION public.complete_account_profile(_name text,_location text,_occupation text,_category text,_kind text) RETURNS timestamptz LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE started timestamptz; first_award boolean; BEGIN IF auth.uid() IS NULL OR NOT public.account_allowed(auth.uid()) THEN RAISE EXCEPTION 'SIGN_IN_REQUIRED'; END IF; IF length(trim(_name)) NOT BETWEEN 1 AND 80 OR length(trim(_location)) NOT BETWEEN 1 AND 80 OR length(trim(_occupation)) NOT BETWEEN 1 AND 100 OR length(trim(_category)) NOT BETWEEN 1 AND 100 OR _kind NOT IN('seeker','employer','owner','business','service') THEN RAISE EXCEPTION 'PROFILE_REQUIRED'; END IF; PERFORM 1 FROM public.profiles WHERE id=auth.uid() FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'PROFILE_REQUIRED'; END IF; SELECT completed_at INTO started FROM public.account_programs WHERE user_id=auth.uid(); first_award:=started IS NULL; UPDATE public.profiles SET full_name=trim(_name),location=trim(_location) WHERE id=auth.uid(); INSERT INTO public.account_programs(user_id,occupation,category,member_kind) VALUES(auth.uid(),trim(_occupation),trim(_category),_kind) ON CONFLICT(user_id) DO UPDATE SET occupation=EXCLUDED.occupation,category=EXCLUDED.category,member_kind=EXCLUDED.member_kind RETURNING completed_at INTO started; IF first_award THEN INSERT INTO public.reward_wallets(user_id,points) VALUES(auth.uid(),265) ON CONFLICT(user_id) DO UPDATE SET points=public.reward_wallets.points+265; END IF; RETURN started; END $$;
REVOKE ALL ON FUNCTION public.complete_account_profile(text,text,text,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.complete_account_profile(text,text,text,text,text) TO authenticated;
CREATE FUNCTION public.set_program_reminders(_enabled boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT public.account_allowed(auth.uid()) THEN RAISE EXCEPTION 'SIGN_IN_REQUIRED'; END IF; UPDATE public.account_programs SET reminder_consent=_enabled WHERE user_id=auth.uid(); IF NOT FOUND THEN RAISE EXCEPTION 'PROFILE_REQUIRED'; END IF; END $$;
REVOKE ALL ON FUNCTION public.set_program_reminders(boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.set_program_reminders(boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.has_goods_membership(_user uuid DEFAULT auth.uid()) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT _user IS NOT NULL AND public.account_allowed(_user) AND (EXISTS(SELECT 1 FROM public.account_programs p WHERE p.user_id=_user AND (now()<p.completed_at+interval '10 days' OR p.sharing_active OR p.referral_free_until>now())) OR EXISTS(SELECT 1 FROM public.profiles p JOIN public.job_post_entitlements e ON e.user_id=p.id JOIN public.membership_payments m ON m.id=e.payment_id WHERE p.id=_user AND p.is_prime AND p.prime_until>(now() AT TIME ZONE 'Asia/Kolkata')::date AND e.starts_at<=now() AND e.ends_at>now() AND m.status='approved' AND m.amount=699 AND m.membership_type='individual')) $$;
CREATE OR REPLACE FUNCTION public.require_post_mobile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.account_programs WHERE user_id=NEW.user_id) THEN RAISE EXCEPTION 'PROFILE_REQUIRED'; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.require_message_mobile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.account_allowed(NEW.sender_id) OR NOT public.account_allowed(NEW.receiver_id) THEN RAISE EXCEPTION 'ACCOUNT_BLOCKED'; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.guard_post_delay() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' THEN NEW.visible_after:=CASE WHEN (NEW.module='job' AND NEW.kind='seeker') OR EXISTS(SELECT 1 FROM public.account_programs WHERE user_id=NEW.user_id AND sharing_active) THEN now() ELSE now()+interval '5 hours' END; ELSIF NEW.visible_after IS DISTINCT FROM OLD.visible_after AND coalesce(current_setting('app.post_review',true),'')<>'1' THEN RAISE EXCEPTION 'POST_DELAY_PROTECTED'; END IF; RETURN NEW; END $$;
CREATE FUNCTION public.activate_program_sharing(_user uuid,_paths text[],_hashes text[],_post uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE path text; hash text; claim uuid; admin_id uuid; BEGIN IF NOT public.account_allowed(_user) THEN RAISE EXCEPTION 'ACCOUNT_BLOCKED'; END IF; PERFORM 1 FROM public.account_programs WHERE user_id=_user FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'PROFILE_REQUIRED'; END IF; IF cardinality(_paths)<>6 OR cardinality(_hashes)<>6 OR (SELECT count(DISTINCT h) FROM unnest(_hashes) h)<>6 THEN RAISE EXCEPTION 'SIX_DISTINCT_IMAGES_REQUIRED'; END IF; FOREACH path IN ARRAY _paths LOOP IF path NOT LIKE _user::text||'/%' OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='sharing-evidence' AND name=path) THEN RAISE EXCEPTION 'INVALID_EVIDENCE'; END IF; END LOOP; IF _post IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.posts WHERE id=_post AND user_id=_user AND status='active') THEN RAISE EXCEPTION 'OWN_POST_REQUIRED'; END IF; FOREACH hash IN ARRAY _hashes LOOP IF hash !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'INVALID_HASH'; END IF; INSERT INTO public.evidence_content_registry(hash,user_id) VALUES(hash,_user); END LOOP; INSERT INTO public.program_evidence(user_id,paths,hashes) VALUES(_user,_paths,_hashes) RETURNING id INTO claim; UPDATE public.account_programs SET sharing_active=true,sharing_started_at=coalesce(sharing_started_at,now()) WHERE user_id=_user; PERFORM set_config('app.post_review','1',true); UPDATE public.posts SET visible_after=now() WHERE user_id=_user AND status='active' AND visible_after>now() AND (_post IS NULL OR id=_post); PERFORM set_config('app.post_review','',true); admin_id:=public.support_admin_id(); IF admin_id IS NOT NULL AND admin_id<>_user THEN INSERT INTO public.messages(sender_id,receiver_id,body,needs_admin) VALUES(_user,admin_id,'స్థితి + 5 సమూహాల ఆధారాలు అందాయి. ఉచిత సభ్యత్వం ప్రారంభమైంది; బయటి పంచుకోవడం ధృవీకరించబడలేదు. ఆధార గుర్తింపు: '||claim::text,true); END IF; RETURN claim; END $$;
REVOKE ALL ON FUNCTION public.activate_program_sharing(uuid,text[],text[],uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.activate_program_sharing(uuid,text[],text[],uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.can_notify(_uid uuid) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE pref public.notification_preferences; zone text; local_now timestamp; used integer; cap integer; BEGIN IF _uid IS NULL OR NOT public.account_allowed(_uid) THEN RETURN false; END IF; SELECT * INTO pref FROM public.notification_preferences WHERE user_id=_uid; zone:=coalesce(pref.timezone,'Asia/Kolkata'); local_now:=now() AT TIME ZONE zone; IF pref.enabled=false THEN RETURN false; END IF; IF pref.quiet_start IS NOT NULL AND ((pref.quiet_start<pref.quiet_end AND local_now::time>=pref.quiet_start AND local_now::time<pref.quiet_end) OR (pref.quiet_start>pref.quiet_end AND (local_now::time>=pref.quiet_start OR local_now::time<pref.quiet_end))) THEN RETURN false; END IF; cap:=least(coalesce(pref.daily_limit,5),5); SELECT count(*) INTO used FROM public.notifications WHERE user_id=_uid AND created_at>=date_trunc('day',local_now) AT TIME ZONE zone; RETURN used<cap; END $$;
CREATE OR REPLACE FUNCTION public.my_notification_quota() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE pref public.notification_preferences; zone text; local_now timestamp; used integer; cap integer; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'SIGN_IN_REQUIRED'; END IF; SELECT * INTO pref FROM public.notification_preferences WHERE user_id=auth.uid(); zone:=coalesce(pref.timezone,'Asia/Kolkata');local_now:=now() AT TIME ZONE zone;cap:=least(coalesce(pref.daily_limit,5),5); SELECT count(*) INTO used FROM public.notifications WHERE user_id=auth.uid() AND created_at>=date_trunc('day',local_now) AT TIME ZONE zone; RETURN jsonb_build_object('used',used,'limit',cap,'remaining',greatest(cap-used,0),'resets_at',(date_trunc('day',local_now)+interval '1 day') AT TIME ZONE zone,'timezone',zone); END $$;
CREATE OR REPLACE FUNCTION public.notify_matches(_post_id uuid) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.posts; m record; n integer:=0; notice uuid; BEGIN IF auth.uid() IS NULL OR NOT public.account_allowed(auth.uid()) THEN RAISE EXCEPTION 'SIGN_IN_REQUIRED'; END IF; IF NOT EXISTS(SELECT 1 FROM public.account_programs WHERE user_id=auth.uid()) THEN RAISE EXCEPTION 'PROFILE_REQUIRED'; END IF; SELECT * INTO p FROM public.posts WHERE id=_post_id AND user_id=auth.uid() AND status='active' AND (visible_after IS NULL OR visible_after<=now()) AND (job_expires_at IS NULL OR job_expires_at>now()); IF p.id IS NULL THEN RAISE EXCEPTION 'OWN_VISIBLE_POST_REQUIRED'; END IF; IF public.is_goods_post(p) AND NOT public.has_goods_membership(auth.uid()) THEN RAISE EXCEPTION 'GOODS_MEMBERSHIP_REQUIRED'; END IF; PERFORM set_config('app.bell_notice','owner',true); FOR m IN SELECT DISTINCT ON(candidate.user_id) candidate.* FROM public.posts candidate JOIN public.account_programs prog ON prog.user_id=candidate.user_id WHERE public.posts_match_area(p,candidate) AND (candidate.visible_after IS NULL OR candidate.visible_after<=now()) AND (candidate.job_expires_at IS NULL OR candidate.job_expires_at>now()) AND ((p.module='vehicle' AND lower(trim(coalesce(p.vehicle_type,'')))=lower(trim(coalesce(candidate.vehicle_type,'')))) OR (p.module='job' AND lower(trim(coalesce(nullif(p.category,''),p.skill,'')))=lower(trim(coalesce(nullif(candidate.category,''),candidate.skill,''))))) ORDER BY candidate.user_id,candidate.created_at DESC LOOP EXIT WHEN n>=5; PERFORM 1 FROM public.profiles WHERE id=m.user_id FOR UPDATE; IF public.can_notify(m.user_id) AND NOT EXISTS(SELECT 1 FROM public.notifications WHERE user_id=m.user_id AND matched_post_id=p.id AND created_at>now()-interval '5 minutes') THEN notice:=NULL; INSERT INTO public.notifications(user_id,post_id,matched_post_id,message) VALUES(m.user_id,m.id,p.id,'గంట కొట్టారు · Bell: '||CASE WHEN p.module='vehicle' THEN coalesce(p.vehicle_type,'వాహనం') ELSE coalesce(p.skill,'పని') END) RETURNING id INTO notice; IF notice IS NOT NULL THEN INSERT INTO public.post_chat_pairs(post_id,member_id,owner_id) VALUES(p.id,m.user_id,p.user_id) ON CONFLICT DO NOTHING; n:=n+1; END IF; END IF; END LOOP; PERFORM set_config('app.bell_notice','',true); RETURN n; END $$;
CREATE OR REPLACE FUNCTION public.ring_post(_post_id uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.posts; caller uuid:=auth.uid(); BEGIN IF caller IS NULL OR NOT public.account_allowed(caller) THEN RAISE EXCEPTION 'SIGN_IN_REQUIRED'; END IF; IF NOT EXISTS(SELECT 1 FROM public.account_programs WHERE user_id=caller) THEN RAISE EXCEPTION 'PROFILE_REQUIRED'; END IF; SELECT * INTO p FROM public.posts WHERE id=_post_id AND status='active' AND (visible_after IS NULL OR visible_after<=now()) AND (job_expires_at IS NULL OR job_expires_at>now()) AND public.account_allowed(user_id); IF p.id IS NULL OR p.user_id=caller THEN RAISE EXCEPTION 'POST_UNAVAILABLE'; END IF; IF public.is_goods_post(p) AND NOT public.has_goods_membership(caller) THEN RAISE EXCEPTION 'GOODS_MEMBERSHIP_REQUIRED'; END IF; INSERT INTO public.post_chat_pairs(post_id,member_id,owner_id) VALUES(p.id,caller,p.user_id) ON CONFLICT DO NOTHING; PERFORM set_config('app.bell_notice','interest',true); PERFORM 1 FROM public.profiles WHERE id=p.user_id FOR UPDATE; IF public.can_notify(p.user_id) THEN INSERT INTO public.notifications(user_id,post_id,message) VALUES(p.user_id,p.id,'మీ ప్రకటనపై సమాచారం కోరారు · Someone rang your post bell'); END IF; IF NOT EXISTS(SELECT 1 FROM public.messages WHERE post_id=p.id AND sender_id=caller AND receiver_id=p.user_id) THEN INSERT INTO public.messages(sender_id,receiver_id,post_id,body) VALUES(caller,p.user_id,p.id,'మీ ప్రకటనపై సమాచారం కావాలి · Interested in your post'); END IF; PERFORM set_config('app.bell_notice','',true); RETURN p.user_id; END $$;
CREATE OR REPLACE FUNCTION public.apply_referral(_code text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE me public.profiles; ref public.profiles; BEGIN IF auth.uid() IS NULL OR NOT public.account_allowed(auth.uid()) THEN RETURN false; END IF; SELECT * INTO me FROM public.profiles WHERE id=auth.uid() FOR UPDATE; IF me.id IS NULL OR me.referred_by IS NOT NULL OR me.created_at<now()-interval '2 days' THEN RETURN false; END IF; SELECT * INTO ref FROM public.profiles WHERE referral_code=upper(trim(_code)); IF ref.id IS NULL OR ref.id=me.id OR NOT public.account_allowed(ref.id) THEN RETURN false; END IF; PERFORM set_config('app.trusted','1',true); UPDATE public.profiles SET referred_by=ref.id,referred_at=now() WHERE id=me.id; PERFORM set_config('app.trusted','',true); RETURN true; END $$;
CREATE FUNCTION public.process_program_referral(_user uuid) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE prog public.account_programs; cnt integer; BEGIN SELECT * INTO prog FROM public.account_programs WHERE user_id=_user FOR UPDATE; IF prog.user_id IS NULL OR NOT public.account_allowed(_user) THEN RETURN 0; END IF; SELECT count(*) INTO cnt FROM public.profiles p JOIN auth.users u ON u.id=p.id WHERE p.referred_by=_user AND p.referred_at>=prog.completed_at+interval '10 days' AND p.created_at>=prog.completed_at+interval '10 days' AND u.email_confirmed_at IS NOT NULL AND public.account_allowed(p.id); IF cnt>=100 AND prog.referral_rewarded_at IS NULL THEN UPDATE public.account_programs SET referral_rewarded_at=now(),referral_free_until=now()+interval '3 months' WHERE user_id=_user; END IF; RETURN cnt; END $$;
REVOKE ALL ON FUNCTION public.process_program_referral(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.process_program_referral(uuid) TO service_role;
CREATE FUNCTION public.my_program_referrals() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cnt integer; BEGIN IF auth.uid() IS NULL OR NOT public.account_allowed(auth.uid()) THEN RAISE EXCEPTION 'SIGN_IN_REQUIRED'; END IF; cnt:=public.process_program_referral(auth.uid()); RETURN jsonb_build_object('count',cnt,'target',100); END $$;
REVOKE ALL ON FUNCTION public.my_program_referrals() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.my_program_referrals() TO authenticated;
CREATE FUNCTION public.dispatch_program_requests() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p record; day_age integer; today date; inserted integer; count_sent integer:=0; id uuid; BEGIN FOR p IN SELECT a.*,coalesce(n.timezone,'Asia/Kolkata') zone FROM public.account_programs a LEFT JOIN public.notification_preferences n ON n.user_id=a.user_id WHERE a.reminder_consent AND NOT a.sharing_active AND public.account_allowed(a.user_id) LOOP PERFORM public.process_program_referral(p.user_id); IF public.has_goods_membership(p.user_id) THEN CONTINUE; END IF; today:=(now() AT TIME ZONE p.zone)::date; day_age:=today-(p.completed_at AT TIME ZONE p.zone)::date; IF day_age NOT BETWEEN 10 AND 13 OR NOT public.can_notify(p.user_id) THEN CONTINUE; END IF; INSERT INTO public.program_reminders(user_id,day) VALUES(p.user_id,today) ON CONFLICT DO NOTHING; GET DIAGNOSTICS inserted=ROW_COUNT; IF inserted=0 THEN CONTINUE; END IF; INSERT INTO public.notifications(user_id,message) VALUES(p.user_id,'సర్, పది రోజులు చూశారు. మీకు ఉపయోగపడితే సభ్యత్వం తీసుకుని ఒక సంవత్సరం మాకు తోడుగా ఉండండి. సరకు వాహన సభ్యత్వం నెలకు ₹699. ఉద్యోగాలు, కార్లు ఉచితం. స్థితి + 5 సమూహాల్లో మా చిత్రం పంచుకుని ఆధారాలు పంపితే ఉచిత సభ్యత్వం కొనసాగుతుంది. మీ ఇష్టం; సూచనలు నిలిపివేయవచ్చు.') RETURNING notifications.id INTO id; UPDATE public.program_reminders SET notification_id=id WHERE user_id=p.user_id AND day=today; count_sent:=count_sent+1; END LOOP; RETURN count_sent; END $$;
REVOKE ALL ON FUNCTION public.dispatch_program_requests() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.dispatch_program_requests() TO service_role;
COMMENT ON TABLE public.program_evidence IS 'Private received uploads, not verified external sharing. Promotional access activates after server validation; no admin approval required.';
COMMENT ON FUNCTION public.complete_account_profile(text,text,text,text,text) IS 'First successful profile completion fixes trial start and awards 265 points once; edits do not restart or re-award.';